const JOBS_BY_ID = new Map<string, SalesforceJob>(SALESFORCE_JOBS.map((job) => [job.id, job]));

export function isSalesforceJobId(value: unknown): value is SalesforceJobId {
  return typeof value === 'string' && JOBS_BY_ID.has(value);
}

export function getSalesforceJob(id: string | null | undefined): SalesforceJob | undefined {
  return id ? JOBS_BY_ID.get(id) : undefined;
}

/** The report type a job's report usually takes; readiness for a release reads as an executive brief. */
export function salesforceJobReportType(
  job: SalesforceJob,
  inputs: Pick<SalesforceJobInputs, 'readinessKind'> = {},
): Exclude<AnalyzeDocumentPresetId, 'auto'> | undefined {
  if (job.id === 'readiness' && inputs.readinessKind === 'release') return 'executive_brief';
  return job.reportTypeId;
}

/**
 * Sessions before 2.9.6 pinned Salesforce lenses (`selectedAnalysisLensIds` on
 * their messages and snapshots). Each reads as the job that took its place, so a
 * restored session keeps its focus. A lens with no job (imported agent evidence)
 * reads as none.
 */
const LEGACY_LENS_JOBS: Record<string, SalesforceJobId> = {
  salesforce_stakeholder_audit: 'audit',
  salesforce_troubleshooting: 'troubleshoot',
  salesforce_dependency_impact: 'change_impact',
  salesforce_access_governance: 'access_review',
  salesforce_process_automation: 'audit',
  salesforce_engineering_handoff: 'handoff',
  salesforce_feature_readiness: 'readiness',
  salesforce_release_readiness: 'readiness',
};

export function salesforceJobFromLegacyLensIds(lensIds: unknown): SalesforceJobId | null {
  if (!Array.isArray(lensIds)) return null;
  for (const lensId of lensIds) {
    if (typeof lensId === 'string' && LEGACY_LENS_JOBS[lensId]) return LEGACY_LENS_JOBS[lensId];
  }
  return null;
}

/** The job a message or snapshot carries: its own, else the one its legacy lens ids read as. */
export function readSalesforceJobId(record: { salesforceJobId?: unknown; selectedAnalysisLensIds?: unknown } | null | undefined): SalesforceJobId | null {
  if (!record) return null;
  if (isSalesforceJobId(record.salesforceJobId)) return record.salesforceJobId;
  return salesforceJobFromLegacyLensIds(record.selectedAnalysisLensIds);
}

/**
 * The job that fits an audit operation the AI chose (the server's synthesis note
 * under Auto): the one whose path starts with it. feature_readiness reads as
 * readiness for either kind.
 */
export function salesforceJobForOperation(operation: string | undefined): SalesforceJob | undefined {
  if (!operation) return undefined;
  return SALESFORCE_JOBS.find((job) => job.operations[0] === operation);
}

function listWords(items: string[], conjunction = 'and'): string {
  if (items.length <= 1) return items[0] ?? '';
  if (items.length === 2) return `${items[0]} ${conjunction} ${items[1]}`;
  return `${items.slice(0, -1).join(', ')}, ${conjunction} ${items[items.length - 1]}`;
}

function withArticle(object: string): string {
  return /^[aeiou]/i.test(object) ? `an ${object}` : `a ${object}`;
}

function clean(list: string[] | undefined): string[] {
  return Array.from(new Set((list ?? []).map((item) => item.trim()).filter(Boolean)));
}

/** The job's details, checked: the first missing required input, or null when the run can start. */
export function missingSalesforceJobDetail(job: SalesforceJob, inputs: SalesforceJobInputs): SalesforceJobDetailKind | null {
  for (const detail of job.details) {
    if (!detail.required) continue;
    switch (detail.kind) {
      case 'question': if (!inputs.question?.trim()) return detail.kind; break;
      case 'objects': if (clean(inputs.objects).length === 0) return detail.kind; break;
      case 'flows': if (clean(inputs.flows).length === 0) return detail.kind; break;
      case 'fields': if (clean(inputs.fields).length === 0) return detail.kind; break;
      case 'limit': if (!inputs.limit?.trim()) return detail.kind; break;
      case 'error': if (!inputs.error?.trim()) return detail.kind; break;
      case 'readiness': if (!inputs.readinessName?.trim()) return detail.kind; break;
      case 'handoff': if (!inputs.handoff?.trim()) return detail.kind; break;
    }
  }
  return null;
}

/**
 * The prompt a job sends, written from its details the way the Diagram view's
 * ask buttons write theirs ("Draw what runs when a Case saves."), with the
 * user's "Anything else?" after it.
 */
export function buildSalesforceJobPrompt(job: SalesforceJob, inputs: SalesforceJobInputs): string {
  const objects = clean(inputs.objects);
  const flows = clean(inputs.flows);
  const fields = clean(inputs.fields);
  let lead: string;
  switch (job.id) {
    case 'explain':
      lead = inputs.question?.trim() || 'Explain how the main automation in this workspace works.';
      break;
    case 'data_model':
      lead = objects.length > 0
        ? `Draw the data model of ${listWords(objects)}.`
        : 'Draw the data model of the org\'s own objects.';
      break;
    case 'flow':
      lead = flows.length === 1
        ? `Draw the Flow ${flows[0]} as a diagram, with every flow it starts.`
        : `Draw the Flows ${listWords(flows)} as a diagram, with every flow they start.`;
      break;
    case 'save_order':
      lead = `Draw what runs when ${listWords(objects.map(withArticle), 'or')} saves.`;
      break;
    case 'change_impact':
      lead = `What would a change to ${listWords(fields)} touch? Build the change impact model.`;
      break;
    case 'field_access':
      lead = `Who can see ${listWords(fields)}? Build the field access model.`;
      break;
    case 'org_limits':
      lead = inputs.limit?.trim()
        ? `When will we hit the ${inputs.limit.trim()} limit? Forecast it from the org's readings.`
        : 'When will we hit our org limits? Forecast them from the org\'s readings.';
      break;
    case 'troubleshoot':
      lead = `Troubleshoot this error:\n\n${inputs.error?.trim() ?? ''}`;
      break;
    case 'audit':
      lead = 'Audit the workspace: its risks, its conflicts and what to fix first.';
      break;
    case 'access_review':
      lead = objects.length > 0
        ? `Review access and governance for ${listWords(objects)}: profiles, permission sets, sharing and broad permissions.`
        : 'Review access and governance: profiles, permission sets, sharing and broad permissions.';
      break;
    case 'readiness': {
      const name = inputs.readinessName?.trim() ?? '';
      lead = inputs.readinessKind === 'release'
        ? `Get the org ready for the ${name} release: what it touches, what it retires, and a checklist.`
        : `Get ready for ${name}: what it touches, its risks, and a checklist.`;
      break;
    }
    case 'handoff':
      lead = `Prepare a developer handoff for: ${inputs.handoff?.trim() ?? ''}`;
      break;
  }
  const notes = inputs.notes?.trim();
  return notes ? `${lead}\n\n${notes}` : lead;
}
